ALTER TABLE APP_DQHI_DEV.BETTR_TEST_DATA_@@@@
  ADD (
  "key" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY
  , "audit_insert_dt" DATE DEFAULT ON NULL SYSDATE
  )
;;;
CREATE VIEW V_BETTR_TEST_DATA_@@@@ (
  KEY
  , VALUE_STR
  , VALUE_NUM
  , VALUE_DT
)

AS (
  SELECT
    "key" BETTR_TEST_DATA_KEY
    , "value_str"
    , "value_num"
    , "value_dt"
  FROM
    APP_DQHI_DEV.BETTR_TEST_DATA_@@@@
)
